package com.gymmind.workout.infrastructure.persistence; import com.gymmind.workout.domain.model.WorkoutRecord; import com.gymmind.workout.domain.repository.WorkoutRecordRepository; import org.springframework.stereotype.Repository; @Repository class JpaWorkoutRecordRepository implements WorkoutRecordRepository { private final SpringDataWorkoutRecordRepository delegate; JpaWorkoutRecordRepository(SpringDataWorkoutRecordRepository d){delegate=d;} public WorkoutRecord save(WorkoutRecord r){return delegate.save(r);} }
